export async function addProductToCart(page, quantity) {
    await page.locator("#quantity").selectOption(quantity);
    await page.getByRole("button", { name: "Add To Cart" }).click();
    await page.waitForLoadState('networkidle');
}

export async function dispatchCartUpdated(page, count) {
    await page.evaluate((c) => { document.dispatchEvent(new CustomEvent('cart:updated', { detail: { count: c } })); }, count);
}

export async function placeOrder(page) {
    await page.getByTestId("place-order-btn").click();
    await page.waitForLoadState('networkidle');
}
